const { Text } = Typography;

function maskAccountNumber(accountNumber: string): string {
  const visible = 4;
  if (accountNumber.length <= visible * 2) {
    return accountNumber;
  }
  const first = accountNumber.slice(0, visible);
  const last = accountNumber.slice(-visible);
  const masked = '*'.repeat(accountNumber.length - visible * 2);
  return `${first}${masked}${last}`;
}

export function Beneficiaries(): JSX.Element {
  const navigate = useNavigate();

  const { data, isLoading, isError } = useQuery<BeneficiaryListResponse>({
    queryKey: ['beneficiaries'],
    queryFn: () => apiClient.get<BeneficiaryListResponse>('/beneficiaries'),
  });

  const pageState: PageState = isLoading
    ? 'LOADING'
    : isError
      ? 'ERROR'
      : 'READY';

  const beneficiaries = data?.items ?? [];

  return (
    <PageContainer
      pageId="customer.beneficiaries"
      state={pageState}
      title="收款人管理"
    >
      <div data-testid="beneficiary-list" style={{ padding: '24px' }}>
        <Button
          type="primary"
          onClick={() => navigate('/transfers/new')}
          style={{ marginBottom: 24 }}
          data-testid="beneficiary-new-transfer"
        >
          新建转账
        </Button>

        {isLoading && <Skeleton active />}

{!isLoading && beneficiaries.length === 0 && !isError && (
          <Empty
            description="暂无收款人"
            data-testid="beneficiary-empty"
          />
        )}

        <Row gutter={[16, 16]}>
          {beneficiaries.map((b) => (
            <Col span={8} key={b.id}>
              <Card
                data-testid={`beneficiary-card-${b.id}`}
                hoverable
                onClick={() => navigate('/transfers/new')}
              >
                <p>
                  <strong data-testid={`beneficiary-name-${b.id}`}>
                    {b.name}
                  </strong>
                </p>
                <p>
                  <Text type="secondary">账号：</Text>
                  <span data-testid={`beneficiary-account-${b.id}`}>
                    {maskAccountNumber(b.accountNumber)}
                  </span>
                </p>
                {b.bankName !== undefined && (
                  <p>
                    <Tag data-testid={`beneficiary-bank-${b.id}`}>
                      {b.bankName}
                    </Tag>
                  </p>
                )}
              </Card>
            </Col>
          ))}
        </Row>
      </div>
    </PageContainer>
  );
}

import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button, Form, Input, Typography, Alert, Space } from 'antd';
import { PageContainer } from '@/components/PageContainer';
import { buildAuthRequest, exchangeCodeForToken } from '@/auth/oidc';
import { setAccessToken } from '@/auth/tokenStore';

const { Title, Text } = Typography;

export function Login(): JSX.Element {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const exchangedRef = useRef(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('code');

    if (!code || exchangedRef.current) return;
    exchangedRef.current = true;

    const storedState = sessionStorage.getItem('oidc_state');
    const returnedState = params.get('state');
    const verifier = sessionStorage.getItem('pkce_verifier');

    if (returnedState !== storedState) {
      setError('OIDC state mismatch — possible CSRF attack.');
      return;
    }
    if (!verifier) {
      setError('Missing PKCE verifier in session.');
      return;
    }

    setLoading(true);
    exchangeCodeForToken(code, verifier)
      .then((token) => {
        setAccessToken(token);
        sessionStorage.removeItem('pkce_verifier');
        sessionStorage.removeItem('oidc_state');
        history.replaceState({}, '', '/portal/login');
        navigate('/dashboard');
      })
      .catch((err: unknown) => {
        setError(
          err instanceof Error ? err.message : 'OIDC token exchange failed.',
        );
      })
      .finally(() => setLoading(false));
  }, [navigate]);

async function handleLogin(): Promise<void> {
    setError(null);
    setLoading(true);
    try {
      const { authorizationUrl, verifier, state } = await buildAuthRequest();
      sessionStorage.setItem('pkce_verifier', verifier);
      sessionStorage.setItem('oidc_state', state);
      window.location.assign(authorizationUrl);
    } catch (err: unknown) {
      setError(
        err instanceof Error ? err.message : 'Failed to initiate login.',
      );
      setLoading(false);
    }
  }

  return (
    <PageContainer pageId="customer.login" state={loading ? 'LOADING' : 'READY'}>
      <div style={{ maxWidth: 420, margin: '0 auto', paddingTop: 64 }}>
        <Title level={2} data-testid="login-title">
          安全登录
        </Title>
        <Text type="secondary">
          使用银行客户身份登录，令牌仅保存在当前页面内存中。
        </Text>

        {error !== null && (
          <Alert
            data-testid="login-error"
            type="error"
            message="登录失败"
            description={error}
            style={{ marginTop: 24 }}
            closable
            onClose={() => setError(null)}
          />
        )}

import { useNavigate } from 'react-router-dom';
